begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();

select ok(not exists(select 1 from pg_roles where rolname='wyp_deployment_rpc' and (rolcanlogin or rolinherit or rolsuper or rolcreatedb or rolcreaterole or rolreplication or rolbypassrls)),'capability reader is a narrow nonlogin role');
select ok(not pg_has_role('authenticator','wyp_deployment_rpc','MEMBER'),'PostgREST cannot impersonate the capability reader');
select ok(not has_schema_privilege('wyp_deployment_rpc','private','CREATE'),'temporary ownership privilege is removed');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.deployment_settings'::regclass),'deployment settings force RLS');
select ok(not has_table_privilege('authenticated','private.deployment_settings','SELECT') and not has_table_privilege('authenticated','private.deployment_settings','UPDATE'),'browser cannot read or mutate infrastructure settings');
select ok(not has_table_privilege('wyp_deployment_rpc','private.deployment_settings','INSERT') and not has_table_privilege('wyp_deployment_rpc','private.deployment_settings','UPDATE') and not has_table_privilege('wyp_deployment_rpc','private.deployment_settings','DELETE'),'runtime capability role cannot change source mode');
select ok(not has_table_privilege('wyp_creator_rpc','private.deployment_settings','UPDATE') and not has_table_privilege('wyp_moderation_rpc','private.deployment_settings','UPDATE') and not has_table_privilege('wyp_media_validator','private.deployment_settings','UPDATE'),'creator operator and validator cannot turn uploads on');
select ok(not has_function_privilege('authenticated','private.uploads_enabled()','EXECUTE') and not has_function_privilege('anon','private.require_uploads_enabled()','EXECUTE'),'internal admission helpers are not public API');
select ok(not exists(select 1 from pg_proc where proowner='wyp_deployment_rpc'::regrole and (proconfig is null or not ('search_path=""'=any(proconfig)))),'capability functions pin empty search paths');

-- The normal disposable stack enables local uploads before its regression suite.
-- Exercise both profiles in a rolled-back transaction without disrupting workers.
update private.deployment_settings set source_mode='youtube-and-upload' where singleton;
insert into auth.users(id,email,email_confirmed_at) values('a1000000-0000-4000-8000-000000000001','capability-creator@example.test',now());
create temporary table capability_state(name text primary key,value jsonb);
grant select,insert,update on capability_state to authenticated,wyp_media_validator;
grant usage on schema extensions to wyp_media_validator;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.enable_creator();
select is(public.get_application_capabilities(),'{"sourceMode":"youtube-and-upload"}'::jsonb,'local mode exposes only its public capability');
insert into capability_state values('video',public.create_creator_video('a1000000-0000-4000-8000-000000000002','fixture.mp4',32,'video/mp4',repeat('a',64)));
insert into capability_state values('scenario',public.create_creator_scenario('a1000000-0000-4000-8000-000000000003'));
insert into capability_state select 'uploaded-draft',public.save_creator_scenario(value->'scenario'->>'id','a1000000-0000-4000-8000-000000000004',0,
 jsonb_set(value->'scenario'->'draft'->'content','{source}',((value->'scenario'->'draft'->'content'->'source')-'url')||'{"kind":"uploaded","assetId":null,"creditUrl":""}'::jsonb)) from capability_state where name='scenario';
reset role;
insert into capability_state select 'before',jsonb_build_object('assets',(select jsonb_agg(to_jsonb(a)) from private.video_assets a),'receipts',(select jsonb_agg(to_jsonb(c)) from private.video_asset_commands c));
update private.deployment_settings set source_mode='youtube-only' where singleton;
set local role anon;
select is(public.get_application_capabilities(),'{"sourceMode":"youtube-only"}'::jsonb,'guest capability projection contains no configuration or secrets');
select throws_like('select * from private.deployment_settings','%permission denied%','anonymous callers cannot inspect settings');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_like($$update private.deployment_settings set source_mode='youtube-and-upload'$$,'%permission denied%','creator cannot override hosted mode');
select throws_ok($$select public.create_creator_video('a1000000-0000-4000-8000-000000000002','fixture.mp4',32,'video/mp4',repeat('a',64))$$,'P0001','UPLOADS_DISABLED','old reservation request cannot bypass disabled admission by replay');
select throws_ok($$select public.get_creator_video_request('a1000000-0000-4000-8000-000000000002')$$,'P0001','UPLOADS_DISABLED','request lookup disabled');
select throws_ok('select public.list_creator_videos()','P0001','UPLOADS_DISABLED','list disabled');
select throws_ok(format('select public.get_creator_video(%L)',value->'video'->>'id'),'P0001','UPLOADS_DISABLED','direct asset lookup disabled') from capability_state where name='video';
select throws_ok(format('select public.get_creator_video_upload_session(%L)',value->'video'->>'id'),'P0001','UPLOADS_DISABLED','old reservation cannot start TUS') from capability_state where name='video';
select throws_ok(format('select public.finish_creator_video_upload_session(%L,%L,%L)',value->'video'->>'id','a1000000-0000-4000-8000-000000000005','http://127.0.0.1:55321/storage/v1/upload/resumable/example'),'P0001','UPLOADS_DISABLED','TUS URL completion disabled') from capability_state where name='video';
select throws_ok(format('select public.release_creator_video_upload_session(%L,%L)',value->'video'->>'id','a1000000-0000-4000-8000-000000000005'),'P0001','UPLOADS_DISABLED','TUS reservation release disabled') from capability_state where name='video';
select throws_ok(format('select public.complete_creator_video_upload(%L,%L,0)',value->'video'->>'id','a1000000-0000-4000-8000-000000000006'),'P0001','UPLOADS_DISABLED','upload finalization disabled') from capability_state where name='video';
select throws_ok(format('select public.retry_creator_video_validation(%L,%L,0)',value->'video'->>'id','a1000000-0000-4000-8000-000000000006'),'P0001','UPLOADS_DISABLED','validation retry disabled') from capability_state where name='video';
select throws_ok(format('select public.begin_creator_video_delete(%L,%L,0)',value->'video'->>'id','a1000000-0000-4000-8000-000000000006'),'P0001','UPLOADS_DISABLED','delete start disabled') from capability_state where name='video';
select throws_ok(format('select public.finish_creator_video_delete(%L,%L)',value->'video'->>'id','a1000000-0000-4000-8000-000000000006'),'P0001','UPLOADS_DISABLED','delete completion disabled') from capability_state where name='video';
select throws_ok(format('select public.authorize_video_playback(%L::jsonb)',jsonb_build_object('kind','creator-asset','assetId',value->'video'->>'id')),'P0001','UPLOADS_DISABLED','playback authorization disabled') from capability_state where name='video';
select ok(not private.video_can_insert('untrusted/source.mp4','{}') and not private.video_can_read('untrusted/source.mp4') and not private.video_can_delete('untrusted/source.mp4'),'Storage predicates reject every operation in hosted mode');
select throws_ok(format('select public.save_creator_scenario(%L,%L,1,%L::jsonb)',value->'scenario'->>'id','a1000000-0000-4000-8000-000000000007',value->'scenario'->'draft'->'content'),'P0001','UPLOADS_DISABLED','null-asset uploaded draft cannot bypass source admission') from capability_state where name='uploaded-draft';
select lives_ok(format('select public.get_creator_scenario(%L)',value->'scenario'->>'id'),'existing uploaded draft remains readable for explicit source replacement') from capability_state where name='uploaded-draft';
select throws_ok(format('select public.get_creator_review_preview(%L,1)',value->'scenario'->>'id'),'P0001','UPLOADS_DISABLED','uploaded review preview disabled') from capability_state where name='uploaded-draft';
select throws_ok(format('select public.review_creator_scenario(%L,%L,1,%L::jsonb)',value->'scenario'->>'id','a1000000-0000-4000-8000-000000000007','{}'),'P0001','UPLOADS_DISABLED','review disabled before new review record') from capability_state where name='uploaded-draft';
select throws_ok(format('select public.publish_creator_scenario(%L,%L,1,%L)',value->'scenario'->>'id','a1000000-0000-4000-8000-000000000007','a1000000-0000-4000-8000-000000000008'),'P0001','UPLOADS_DISABLED','publication disabled before receipt replay') from capability_state where name='uploaded-draft';
select lives_ok('select public.list_library_previews()','public YouTube discovery still works');
reset role;
set local role wyp_media_validator;
select set_config('request.jwt.claims','{"role":"wyp_media_validator"}',true);
select throws_ok('select public.report_video_validator_heartbeat()','P0001','UPLOADS_DISABLED','heartbeat disabled');
select throws_ok('select public.claim_video_validation()','P0001','UPLOADS_DISABLED','worker claim disabled');
select throws_ok($$select public.renew_video_validation_lease('a1000000-0000-4000-8000-000000000009','a1000000-0000-4000-8000-000000000010')$$,'P0001','UPLOADS_DISABLED','worker lease renewal disabled');
select throws_ok($$select public.complete_video_validation('a1000000-0000-4000-8000-000000000009','a1000000-0000-4000-8000-000000000010','version','{}')$$,'P0001','UPLOADS_DISABLED','worker completion disabled');
select throws_ok($$select public.fail_video_validation('a1000000-0000-4000-8000-000000000009','a1000000-0000-4000-8000-000000000010','MEDIA_PROBE_FAILED',true)$$,'P0001','UPLOADS_DISABLED','worker failure mutation disabled');
reset role;
select is(jsonb_build_object('assets',(select jsonb_agg(to_jsonb(a)) from private.video_assets a),'receipts',(select jsonb_agg(to_jsonb(c)) from private.video_asset_commands c)),(select value from capability_state where name='before'),'denied commands did not alter assets or receipts');
delete from private.deployment_settings;
select ok(not private.uploads_enabled(),'missing settings fail closed');
select throws_ok('select public.get_application_capabilities()','P0001','STORAGE_UNAVAILABLE','missing singleton is an explicit unavailable state');
select * from finish();
rollback;
